import { Controller, Get, Post, Patch, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '인사 담당자';
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const TYPES = ['ACQUISITION', 'LOSS'];
// 가정: 신고서 사용 여부의 등록 시 초기값은 false (BEHAVIOR.md 값의 출처)
const INITIAL_USED_IN_REPORT = false;

const SELECT_COLS = `
  social_insurance_enrollment_id AS "socialInsuranceEnrollmentId",
  employee_id AS "employeeId",
  enrollment_type AS "enrollmentType",
  event_date AS "eventDate",
  loss_reason AS "lossReason",
  used_in_report AS "usedInReport"
`;

function invalid(message: string): ApiError {
  return new ApiError(422, 'INVALID_ENROLLMENT_INPUT', message);
}

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || String(v).trim() === '';
}

function isDateText(v: unknown): boolean {
  return typeof v === 'string' && DATE_RE.test(v);
}

function isIntegerValue(v: unknown): boolean {
  return !isBlank(v) && Number.isInteger(Number(v));
}

@Controller('api/v1')
export class FnSfr02201Controller {
  @Post('/social-insurance-enrollments')
  @HttpCode(200)
  async createSocialInsuranceEnrollment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    if (!isIntegerValue(data.employeeId)) {
      throw invalid('임직원을 선택해 주세요.');
    }
    if (typeof data.enrollmentType !== 'string' || !TYPES.includes(data.enrollmentType)) {
      throw invalid('대상자 구분을 선택해 주세요.');
    }
    if (!isDateText(data.eventDate)) {
      throw invalid('취득일·상실일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const enrollmentType = data.enrollmentType;
    let lossReason: string | null = null;
    if (enrollmentType === 'LOSS') {
      if (isBlank(data.lossReason)) {
        throw invalid('상실 사유를 입력해 주세요.');
      }
      lossReason = String(data.lossReason);
      if (lossReason.length > 200) {
        throw invalid('상실 사유는 200자 이내로 입력해 주세요.');
      }
    }
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId: Number(data.employeeId) },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '대상 임직원을 찾을 수 없습니다.');
      }
      const dup = await db.query(
        `SELECT social_insurance_enrollment_id FROM social_insurance_enrollment
         WHERE employee_id = CAST(:employeeId AS bigint) AND enrollment_type = :enrollmentType`,
        { employeeId: Number(data.employeeId), enrollmentType },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'ENROLLMENT_DUPLICATED', '동일 임직원이 같은 구분으로 이미 등록되어 있습니다.');
      }
      const rows = await db.query(
        `INSERT INTO social_insurance_enrollment
           (employee_id, enrollment_type, event_date, loss_reason, used_in_report, created_at, updated_at)
         VALUES
           (CAST(:employeeId AS bigint), :enrollmentType, CAST(:eventDate AS date), :lossReason, :usedInReport, now(), now())
         RETURNING
           social_insurance_enrollment_id AS "socialInsuranceEnrollmentId",
           employee_id AS "employeeId",
           enrollment_type AS "enrollmentType",
           event_date AS "eventDate"`,
        {
          employeeId: Number(data.employeeId),
          enrollmentType,
          eventDate: data.eventDate,
          lossReason,
          usedInReport: INITIAL_USED_IN_REPORT,
        },
      );
      return rows[0];
    });
  }

  @Get('/social-insurance-enrollments')
  async listSocialInsuranceEnrollments(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const pageNo = isIntegerValue(query.page) ? Math.max(0, Number(query.page)) : 0;
    const sizeRaw = isIntegerValue(query.size) ? Number(query.size) : 20;
    const size = Math.min(200, Math.max(1, sizeRaw));
    const conditions: string[] = [];
    const params: Record<string, unknown> = { limit: size, offset: pageNo * size };
    if (!isBlank(query.enrollmentType)) {
      if (!TYPES.includes(String(query.enrollmentType))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '대상자 구분 값이 올바르지 않습니다.');
      }
      conditions.push('enrollment_type = :enrollmentType');
      params.enrollmentType = String(query.enrollmentType);
    }
    if (!isBlank(query.employeeId)) {
      if (!isIntegerValue(query.employeeId)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '임직원 값이 올바르지 않습니다.');
      }
      conditions.push('employee_id = CAST(:employeeId AS bigint)');
      params.employeeId = Number(query.employeeId);
    }
    const where = conditions.length > 0 ? 'WHERE ' + conditions.join(' AND ') : '';
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT ${SELECT_COLS}
         FROM social_insurance_enrollment
         ${where}
         ORDER BY social_insurance_enrollment_id DESC
         LIMIT :limit OFFSET :offset`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM social_insurance_enrollment ${where}`,
        params,
      );
      return { items, page: pageNo, size, total: Number(counts[0].total) };
    });
  }

  @Patch('/social-insurance-enrollments/:socialInsuranceEnrollmentId')
  async updateSocialInsuranceEnrollment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const idText = req.params['socialInsuranceEnrollmentId'];
    if (!isIntegerValue(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '대상자 ID가 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const hasDate = !isBlank(data.eventDate);
    const hasReason = data.lossReason !== undefined && data.lossReason !== null;
    if (hasDate && !isDateText(data.eventDate)) {
      throw invalid('날짜를 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    if (hasReason && String(data.lossReason).length > 200) {
      throw invalid('상실 사유는 200자 이내로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT enrollment_type AS "enrollmentType", used_in_report AS "usedInReport"
         FROM social_insurance_enrollment
         WHERE social_insurance_enrollment_id = CAST(:id AS bigint)`,
        { id: Number(idText) },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ENROLLMENT_NOT_FOUND', '대상자를 찾을 수 없습니다.');
      }
      if (rows[0].usedInReport === true) {
        throw new ApiError(409, 'ENROLLMENT_USED_IN_REPORT', '신고서 작성에 이미 사용된 대상자는 수정할 수 없습니다.');
      }
      const sets: string[] = ['updated_at = now()'];
      const params: Record<string, unknown> = { id: Number(idText) };
      if (hasDate) {
        sets.push('event_date = CAST(:eventDate AS date)');
        params.eventDate = data.eventDate;
      }
      if (hasReason) {
        if (rows[0].enrollmentType === 'LOSS' && isBlank(data.lossReason)) {
          throw invalid('상실 대상자는 상실 사유가 필요합니다.');
        }
        sets.push('loss_reason = :lossReason');
        params.lossReason = isBlank(data.lossReason) ? null : String(data.lossReason);
      }
      await db.execute(
        `UPDATE social_insurance_enrollment SET ${sets.join(', ')}
         WHERE social_insurance_enrollment_id = CAST(:id AS bigint)`,
        params,
      );
      return { socialInsuranceEnrollmentId: Number(idText) };
    });
  }

  @Delete('/social-insurance-enrollments/:socialInsuranceEnrollmentId')
  async deleteSocialInsuranceEnrollment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const idText = req.params['socialInsuranceEnrollmentId'];
    if (!isIntegerValue(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '대상자 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT used_in_report AS "usedInReport"
         FROM social_insurance_enrollment
         WHERE social_insurance_enrollment_id = CAST(:id AS bigint)`,
        { id: Number(idText) },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ENROLLMENT_NOT_FOUND', '대상자를 찾을 수 없습니다.');
      }
      if (rows[0].usedInReport === true) {
        throw new ApiError(409, 'ENROLLMENT_USED_IN_REPORT', '신고서 작성에 이미 사용된 대상자는 삭제할 수 없습니다.');
      }
      await db.execute(
        'DELETE FROM social_insurance_enrollment WHERE social_insurance_enrollment_id = CAST(:id AS bigint)',
        { id: Number(idText) },
      );
      return {};
    });
  }
}

