import { useState } from 'react';
import {
  call, useData, Badge, Num, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Tiles,
  Form, Field, TextInput, DateInput, Select, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const TYPE_OPTIONS: [string, string][] = [['ACQUISITION', '취득'], ['LOSS', '상실']];
const TYPE_NAME: Record<string, string> = { ACQUISITION: '취득', LOSS: '상실' };

export default function FnSfr02201Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [draftType, setDraftType] = useState('');
  const [draftEmployee, setDraftEmployee] = useState<number | string>('');
  const [applied, setApplied] = useState<{ type: string; employee: number | string }>({ type: '', employee: '' });
  const [mode, setMode] = useState<'' | 'create' | 'edit' | 'delete' | 'detail'>('');
  const [target, setTarget] = useState<Row | null>(null);

  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [enrollmentType, setEnrollmentType] = useState('');
  const [eventDate, setEventDate] = useState('');
  const [lossReason, setLossReason] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/social-insurance-enrollments', role, undefined, {
      enrollmentType: applied.type,
      employeeId: applied.employee,
      page,
      size: 20,
    }),
    [page, applied, role],
  );
  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;

  function close() {
    setMode('');
    setTarget(null);
  }

  function openCreate() {
    setEmployeeId('');
    setEnrollmentType('');
    setEventDate('');
    setLossReason('');
    setTarget(null);
    setMode('create');
  }

  function openEdit(row: Row) {
    setTarget(row);
    setEventDate(String(row.eventDate ?? '').slice(0, 10));
    setLossReason(String(row.lossReason ?? ''));
    setMode('edit');
  }

  function openDelete(row: Row) {
    setTarget(row);
    setMode('delete');
  }

  function search() {
    setPage(0);
    setApplied({ type: draftType, employee: draftEmployee });
  }

  function reset() {
    setDraftType('');
    setDraftEmployee('');
    setPage(0);
    setApplied({ type: '', employee: '' });
  }

  async function submitCreate() {
    if (employeeId === '' || !enrollmentType || !eventDate) {
      throw new Error('임직원, 대상자 구분, 취득일·상실일은 필수입니다.');
    }
    if (enrollmentType === 'LOSS' && !lossReason.trim()) {
      throw new Error('상실 대상자는 상실 사유를 입력해 주세요.');
    }
    await call('POST', '/social-insurance-enrollments', role, {
      employeeId,
      enrollmentType,
      eventDate,
      lossReason: enrollmentType === 'LOSS' ? lossReason : undefined,
    });
    notify('대상자를 등록했습니다.');
    close();
    setPage(0);
    list.reload();
  }

  async function submitEdit() {
    if (!target) return;
    if (!eventDate) {
      throw new Error('취득일·상실일을 입력해 주세요.');
    }
    if (target.enrollmentType === 'LOSS' && !lossReason.trim()) {
      throw new Error('상실 대상자는 상실 사유를 입력해 주세요.');
    }
    const body: Row = { eventDate };
    if (target.enrollmentType === 'LOSS') {
      body.lossReason = lossReason;
    }
    await call('PATCH', '/social-insurance-enrollments/' + String(target.socialInsuranceEnrollmentId), role, body);
    notify('대상자를 수정했습니다.');
    close();
    list.reload();
  }

  async function submitDelete() {
    if (!target) return;
    await call('DELETE', '/social-insurance-enrollments/' + String(target.socialInsuranceEnrollmentId), role);
    notify('대상자를 삭제했습니다.');
    close();
    list.reload();
  }

  const acquisitionCount = rows.filter((r) => r.enrollmentType === 'ACQUISITION').length;
  const lossCount = rows.filter((r) => r.enrollmentType === 'LOSS').length;

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>대상자 현황</h2>
        <Tiles
          items={[
            ['전체 대상자', <Num value={total} />],
            ['이 쪽의 취득', <Num value={acquisitionCount} />],
            ['이 쪽의 상실', <Num value={lossCount} />],
          ]}
        />
      </section>
      <section className='box span-12'>
        <h2>취득·상실 대상자</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='대상자 구분'>
            <Select value={draftType} onChange={setDraftType} options={TYPE_OPTIONS} placeholder='전체' />
          </Field>
          <Field label='임직원'>
            <LookupSelect table='employee' role={role} value={draftEmployee} onChange={setDraftEmployee} placeholder='전체' />
          </Field>
        </Filters>
        <Band total={total}>
          <button type='button' onClick={openCreate}>대상자 등록</button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          rows={rows}
          empty='등록된 대상자가 없습니다.'
          onRowClick={(row) => {
            setTarget(row);
            setMode('detail');
          }}
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table='employee' role={role} value={r.employeeId} /> },
            { key: 'enrollmentType', label: '대상자 구분', render: (r) => <Badge value={TYPE_NAME[String(r.enrollmentType)] ?? r.enrollmentType} /> },
            { key: 'eventDate', label: '취득일·상실일', render: (r) => <DateText value={r.eventDate} /> },
            { key: 'lossReason', label: '상실 사유' },
            { key: 'usedInReport', label: '신고서 사용 여부', render: (r) => (r.usedInReport ? '사용' : '미사용') },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (r.usedInReport === true ? null : (
                <span>
                  <button type='button' onClick={(e) => { e.stopPropagation(); openEdit(r); }}>수정</button>
                  <button type='button' onClick={(e) => { e.stopPropagation(); openDelete(r); }}>삭제</button>
                </span>
              )),
            },
          ]}
        />
        <Pager page={page} size={20} total={total} onPage={setPage} />
      </section>

      {mode === 'create' ? (
        <Drawer title='대상자 등록' onClose={close}>
          <Form onSubmit={submitCreate} submit='등록'>
            <Field label='임직원' required>
              <LookupSelect table='employee' role={role} value={employeeId} onChange={setEmployeeId} />
            </Field>
            <Field label='대상자 구분' required>
              <Select value={enrollmentType} onChange={setEnrollmentType} options={TYPE_OPTIONS} />
            </Field>
            <Field label='취득일·상실일' required>
              <DateInput value={eventDate} onChange={setEventDate} />
            </Field>
            {enrollmentType === 'LOSS' ? (
              <Field label='상실 사유' required wide>
                <TextInput value={lossReason} onChange={setLossReason} />
              </Field>
            ) : null}
          </Form>
        </Drawer>
      ) : null}

      {mode === 'edit' && target ? (
        <Drawer title='대상자 수정' onClose={close}>
          <Form onSubmit={submitEdit} submit='수정'>
            <Field label='취득일·상실일' required>
              <DateInput value={eventDate} onChange={setEventDate} />
            </Field>
            {target.enrollmentType === 'LOSS' ? (
              <Field label='상실 사유' required wide>
                <TextInput value={lossReason} onChange={setLossReason} />
              </Field>
            ) : null}
          </Form>
        </Drawer>
      ) : null}

      {mode === 'delete' && target ? (
        <Drawer title='대상자 삭제' onClose={close}>
          <Form onSubmit={submitDelete} submit='삭제' danger note='선택한 대상자를 삭제합니다. 계속하시겠습니까?'>
            <Pairs
              items={[
                ['임직원', <RefName table='employee' role={role} value={target.employeeId} />],
                ['대상자 구분', TYPE_NAME[String(target.enrollmentType)] ?? String(target.enrollmentType)],
                ['취득일·상실일', <DateText value={target.eventDate} />],
              ]}
            />
          </Form>
        </Drawer>
      ) : null}

      {mode === 'detail' && target ? (
        <Drawer title='대상자 상세' onClose={close}>
          <Pairs
            items={[
              ['임직원', <RefName table='employee' role={role} value={target.employeeId} />],
              ['대상자 구분', <Badge value={TYPE_NAME[String(target.enrollmentType)] ?? target.enrollmentType} />],
              ['취득일·상실일', <DateText value={target.eventDate} />],
              ['상실 사유', String(target.lossReason ?? '')],
              ['신고서 사용 여부', target.usedInReport ? '사용' : '미사용'],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
